  <div class="page-head"><div><h1>設定</h1><div class="subtle">外部連携の設定はここに集約します。</div></div></div>
  <div class="settings-nav"><button type="button" data-setting="smtp" class="active">SMTP</button><button type="button" data-setting="kintone">kintone</button></div>
  <div class="settings-panel active" id="setting-smtp"><div class="card"><h2 class="section-title">SMTP設定</h2><div class="grid2"><div class="field"><label>ホスト</label><input id="smtpHost" type="text" value="smtp.example.com"></div><div class="field"><label>ポート</label><input id="smtpPort" type="text" value="587"></div><div class="field"><label>暗号化</label><select><option>None</option><option selected>TLS</option><option>SSL</option></select></div><div class="field"><label>ユーザー名</label><input type="text" value="notify@example.com"></div><div class="field"><label>パスワード</label><input type="password" value="password"></div><div class="field"><label>送信元メール</label><input type="text" value="notify@example.com"></div></div><div class="field"><label>送信元表示名</label><input type="text" value="アンケート事務局"></div><div class="row-actions"><button type="button" class="btn secondary" id="smtpTestBtn">接続確認</button><button type="button" class="btn" id="smtpSaveBtn">保存する</button></div></div></div>
  <div class="settings-panel" id="setting-kintone"><div class="card"><h2 class="section-title">kintone設定</h2><div class="grid2"><div class="field"><label>サブドメイン</label><input type="text" value="example.cybozu.com"></div><div class="field"><label>対象アプリID</label><input type="text" value="12"></div><div class="field"><label>ログイン名</label><input type="text" value="api_user"></div><div class="field"><label>パスワード</label><input type="password" value="password"></div><div class="field"><label>プロキシ host:port</label><input type="text" placeholder="proxy.example.com:8080"></div><div class="field"><label>SSL証明書検証</label><select><option selected>無効</option><option>有効</option></select></div></div><div class="kstep"><span class="current">1 接続設定</span><span>2 フィールド取得</span><span>3 マッピング</span><span>4 プレビュー</span><span>5 同期</span></div><div class="row-actions"><button type="button" class="btn secondary" id="kintoneTestBtn">接続確認</button><button type="button" class="btn secondary" id="kintoneFieldsBtn">フィールド取得</button><button type="button" class="btn" id="kintoneSaveBtn">設定を保存</button></div><div id="kintoneMapping" class="muted-box" style="display:none;margin-top:14px"><b>フィールドマッピング</b><div class="grid2" style="margin-top:10px"><div class="field"><label>顧客名</label><select><option>customer_name</option></select></div><div class="field"><label>メールアドレス</label><select><option>email</option></select></div><div class="field"><label>住所</label><select><option>address</option><option>prefecture</option><option>city</option></select></div><div class="field"><label>電話番号</label><select><option>phone</option></select></div></div><button type="button" class="btn" id="kintonePreviewBtn">マッピング確認・プレビュー</button></div></div></div>
</section>

<section class="page" id="page-respondent">
  <div class="external"><div class="respondent-card"><div class="subtle">個別回答URL</div><h1>顧客満足度調査 2026上期</h1><div class="respondent-step"><div class="step active" data-rstep="1">1 回答者情報</div><div class="step" data-rstep="2">2 アンケート</div><div class="step" data-rstep="3">3 完了</div></div>
    <div class="respondent-screen active" id="rinfo"><div class="warning">このURLは個別回答用です。最初に回答者情報を入力してください。</div><div class="field"><label>組織名（必須）</label><input id="rOrg" type="text" placeholder="株式会社サンプル"></div><div class="field"><label>部署名</label><input id="rDept" type="text" placeholder="営業部"></div><div class="field"><label>メールアドレス（必須）</label><input id="rEmail" type="email" placeholder="name@example.com"></div><button type="button" class="btn" id="startAnswerBtn">回答を開始する</button></div>
    <div class="respondent-screen" id="rquestions"><div class="field"><label>Q1. お住まいの地域を教えてください（必須）</label><label><input type="radio" name="rq1"> 北海道・東北</label><br><label><input type="radio" name="rq1"> 関東</label><br><label><input type="radio" name="rq1"> その他</label></div><div class="field"><label>Q2. ご利用中のサービス</label><label><input type="checkbox"> サービスA</label><br><label><input type="checkbox"> サービスB</label></div><div class="field"><label>Q3. ご自由にご意見をお書きください</label><textarea rows="5"></textarea></div><button type="button" class="btn" id="submitAnswerBtn">回答を送信する</button></div>
    <div class="respondent-screen" id="rdone"><div class="muted-box"><b>回答ありがとうございました。</b><p class="subtle">この個別回答URLの状態は「回答済み」になりました。再送信はできません。</p></div></div>
  </div></div>
</section>
</main>

<div class="notice" id="notice"><div class="notice-box"><button type="button" class="notice-close" id="noticeClose">×</button><div class="notice-title" id="noticeTitle"></div><div id="noticeText"></div></div></div>
<div class="modal" id="confirmModal"><div class="modal-box"><h2 id="modalTitle">確認</h2><p id="modalText" class="subtle"></p><div class="modal-actions"><button type="button" class="btn secondary" id="modalCancel">キャンセル</button><button type="button" class="btn" id="modalOk">実行する</button></div></div></div>

<script>
document.addEventListener('DOMContentLoaded', function(){
  const pages = document.querySelectorAll('.page');
  const navButtons = document.querySelectorAll('.nav button');
  let currentSurvey = 's1';
  let currentDetailTab = 'overview';
  let noticeTimer = null;

  const surveyData = {
    s1:{name:'顧客満足度調査 2026上期',status:'open',statusLabel:'公開中',danger:'終了する'},
    s2:{name:'新商品コンセプトアンケート',status:'draft',statusLabel:'下書き',danger:'削除する'},
    s3:{name:'社内イベント参加意向調査',status:'closed',statusLabel:'終了',danger:'削除する'}
  };

  function showPage(name){
    pages.forEach(function(p){p.classList.remove('active')});
    const target=document.getElementById('page-'+name); if(target) target.classList.add('active');
    navButtons.forEach(function(b){b.classList.toggle('active', b.dataset.page===name || (name==='editor'&&b.dataset.page==='surveys') || (name==='detail'&&b.dataset.page==='surveys'))});
  }

  function showNotice(type,title,text){
    const notice=document.getElementById('notice'); const box=notice?notice.querySelector('.notice-box'):null; const t=document.getElementById('noticeTitle'); const x=document.getElementById('noticeText');
    if(!notice||!box||!t||!x)return; notice.className='notice show '+type; t.textContent=title; x.textContent=text; if(noticeTimer)clearTimeout(noticeTimer); noticeTimer=setTimeout(function(){notice.classList.remove('show')},7000);
  }

  function openConfirm(title,text,onOk){
    const modal=document.getElementById('confirmModal'); const mt=document.getElementById('modalTitle'); const mx=document.getElementById('modalText'); const ok=document.getElementById('modalOk');
    if(!modal||!mt||!mx||!ok)return; mt.textContent=title; mx.textContent=text; modal.classList.add('show');
    const handler=function(){modal.classList.remove('show');ok.removeEventListener('click',handler);onOk()}; ok.addEventListener('click',handler);
  }

  function setDetailTab(tab){
    currentDetailTab=tab;
    document.querySelectorAll('#detailTabs button').forEach(function(b){b.classList.toggle('active',b.dataset.tab===tab)});
    document.querySelectorAll('.tab-panel').forEach(function(p){p.classList.toggle('active',p.id==='panel-'+tab)});
  }

  function openDetail(id,tab){
    currentSurvey=id||'s1'; const d=surveyData[currentSurvey]||surveyData.s1; const name=document.getElementById('detailName'); const meta=document.getElementById('detailMeta'); const status=document.getElementById('overviewStatus'); const danger=document.getElementById('detailDangerBtn'); const primary=document.getElementById('detailPrimaryBtn');
    if(name)name.textContent=d.name; if(meta)meta.textContent=d.statusLabel+' ・ '+(currentSurvey==='s2'?'公開期間未設定':'2026/09/10 ～ 2026/10/10'); if(status)status.textContent=d.statusLabel; if(danger){danger.textContent=d.danger;danger.classList.toggle('danger',d.danger==='終了する')}; if(primary)primary.disabled=d.status==='closed'; showPage('detail'); setDetailTab(tab||'overview');
  }

  navButtons.forEach(function(btn){if(!btn)return;btn.addEventListener('click',function(){const p=btn.dataset.page;if(p)showPage(p)})});
  document.querySelectorAll('[data-go]').forEach(function(btn){if(!btn)return;btn.addEventListener('click',function(){showPage(btn.dataset.go)})});
  document.querySelectorAll('.survey-open').forEach(function(btn){if(!btn)return;btn.addEventListener('click',function(){const row=btn.closest('tr');if(row)openDetail(row.dataset.survey,'overview')})});

  const newBtn=document.getElementById('newSurveyBtn'); if(newBtn)newBtn.addEventListener('click',function(){const title=document.getElementById('editorTitle');if(title)title.textContent='アンケート作成';showPage('editor')});
  const detailEdit=document.getElementById('detailEditBtn'); if(detailEdit)detailEdit.addEventListener('click',function(){const title=document.getElementById('editorTitle');if(title)title.textContent='アンケート編集';showPage('editor')});
  const qEdit=document.getElementById('questionsEditBtn'); if(qEdit)qEdit.addEventListener('click',function(){const title=document.getElementById('editorTitle');if(title)title.textContent='アンケート編集';showPage('editor')});
  document.querySelectorAll('#detailTabs button').forEach(function(btn){if(!btn)return;btn.addEventListener('click',function(){setDetailTab(btn.dataset.tab)})});
  document.querySelectorAll('[data-detail-tab]').forEach(function(btn){if(!btn)return;btn.addEventListener('click',function(){setDetailTab(btn.dataset.detailTab)})});

  const primary=document.getElementById('detailPrimaryBtn'); if(primary)primary.addEventListener('click',function(){setDetailTab('send')});
  const danger=document.getElementById('detailDangerBtn'); if(danger)danger.addEventListener('click',function(){const d=surveyData[currentSurvey];if(!d)return;if(d.status==='open'){openConfirm('アンケートを終了しますか？','終了すると回答者は回答できなくなります。',function(){d.status='closed';d.statusLabel='終了';d.danger='削除する';updateSurveyRow(currentSurvey);openDetail(currentSurvey,'overview');showNotice('success','終了しました','アンケートを終了しました。')})}else{openConfirm('アンケートを削除しますか？','この操作は取り消せません。',function(){const row=document.querySelector('tr[data-survey="'+currentSurvey+'"]');if(row)row.remove();showPage('surveys');showNotice('success','削除しました','アンケートを削除しました。')})}});

  function updateSurveyRow(id){const d=surveyData[id];const row=document.querySelector('tr[data-survey="'+id+'"]');if(!row||!d)return;const badge=row.querySelector('[data-status="'+id+'"]');if(!badge)return;badge.textContent=d.statusLabel;badge.className='badge '+d.status}

  const saveEditor=document.getElementById('saveEditorBtn'); if(saveEditor)saveEditor.addEventListener('click',function(){const name=document.getElementById('editorName');if(!name||!name.value.trim()){showNotice('error','保存できません','アンケート名を入力してください。');return}showNotice('success','保存しました','アンケート情報を保存しました。');setTimeout(function(){showPage('surveys')},350)});
  const addQuestion=document.getElementById('addQuestionBtn'); if(addQuestion)addQuestion.addEventListener('click',function(){showNotice('success','質問を追加','新しい質問の編集欄を追加しました。')});
  const addGroup=document.getElementById('addGroupBtn'); if(addGroup)addGroup.addEventListener('click',function(){showNotice('success','グループを追加','新しいグループを追加しました。')});
  document.querySelectorAll('.delete-question').forEach(function(btn){if(!btn)return;btn.addEventListener('click',function(){const q=btn.closest('.question');if(q)q.remove();showNotice('success','削除しました','質問を削除しました。')})});

  const issue=document.getElementById('issueIndividualBtn'); if(issue)issue.addEventListener('click',function(){const box=document.getElementById('individualUrlBox');if(box)box.style.display='block';showNotice('success','個別回答URLを発行しました','回答者情報入力前の状態で発行しました。')});
  const openResp=document.getElementById('openRespondentBtn'); if(openResp)openResp.addEventListener('click',function(){showPage('respondent');setRespondentStep(1)});
  const copy=document.getElementById('copyUrlBtn'); if(copy)copy.addEventListener('click',async function(){const url=document.getElementById('individualUrl');if(!url)return;try{await navigator.clipboard.writeText(url.textContent);showNotice('success','コピーしました','個別回答URLをクリップボードへコピーしました。')}catch(e){showNotice('error','コピーできませんでした','URLを選択してコピーしてください。')}});
  const send=document.getElementById('sendMailBtn'); if(send)send.addEventListener('click',function(){send.disabled=true;send.classList.add('loading');setTimeout(function(){send.disabled=false;send.classList.remove('loading');showNotice('error','送信できません','SMTP設定が未確認のため、送信を中止しました。設定画面で接続確認を行ってください。')},650)});

  document.querySelectorAll('#recipientList input[type="checkbox"]').forEach(function(cb){if(!cb)return;cb.addEventListener('change',function(){const checked=document.querySelectorAll('#recipientList input[type="checkbox"]:checked').length;const count=document.getElementById('selectedCount');if(count)count.textContent=checked+'名を選択中'})});
  const search=document.getElementById('recipientSearch');if(search)search.addEventListener('input',function(){const q=search.value.toLowerCase();document.querySelectorAll('#recipientList .recipient').forEach(function(r){r.style.display=r.textContent.toLowerCase().includes(q)?'flex':'none'})});
  const customerSearch=document.getElementById('customerSearch');if(customerSearch)customerSearch.addEventListener('input',function(){const q=customerSearch.value.toLowerCase();document.querySelectorAll('#customerRows tr').forEach(function(r){r.style.display=r.textContent.toLowerCase().includes(q)?'':'none'})});
  const sync=document.getElementById('syncCustomersBtn');if(sync)sync.addEventListener('click',function(){sync.disabled=true;sync.classList.add('loading');setTimeout(function(){sync.disabled=false;sync.classList.remove('loading');showNotice('success','同期しました','kintoneから顧客情報を取得しました。')},700)});

  document.querySelectorAll('.settings-nav button').forEach(function(btn){if(!btn)return;btn.addEventListener('click',function(){document.querySelectorAll('.settings-nav button').forEach(function(b){b.classList.remove('active')});btn.classList.add('active');document.querySelectorAll('.settings-panel').forEach(function(p){p.classList.remove('active')});const panel=document.getElementById('setting-'+btn.dataset.setting);if(panel)panel.classList.add('active')})});
  const smtpTest=document.getElementById('smtpTestBtn');if(smtpTest)smtpTest.addEventListener('click',function(){smtpTest.disabled=true;smtpTest.classList.add('loading');setTimeout(function(){smtpTest.disabled=false;smtpTest.classList.remove('loading');showNotice('error','SMTP接続エラー','SMTPサーバへ接続できませんでした。ホスト・ポート・暗号化方式を確認してください。')},700)});
  const smtpSave=document.getElementById('smtpSaveBtn');if(smtpSave)smtpSave.addEventListener('click',function(){smtpSave.disabled=true;smtpSave.classList.add('loading');setTimeout(function(){smtpSave.disabled=false;smtpSave.classList.remove('loading');showNotice('success','保存しました','SMTP設定を保存しました。')},500)});
  const ktTest=document.getElementById('kintoneTestBtn');if(ktTest)ktTest.addEventListener('click',function(){ktTest.disabled=true;setTimeout(function(){ktTest.disabled=false;showNotice('success','接続確認成功','kintoneへ接続できました。')},700)});
  const ktFields=document.getElementById('kintoneFieldsBtn');if(ktFields)ktFields.addEventListener('click',function(){ktFields.disabled=true;setTimeout(function(){ktFields.disabled=false;const m=document.getElementById('kintoneMapping');if(m)m.style.display='block';showNotice('success','取得しました','最新のkintoneフィールド定義を取得しました。')},700)});
  const ktSave=document.getElementById('kintoneSaveBtn');if(ktSave)ktSave.addEventListener('click',function(){showNotice('success','保存しました','kintone設定を保存しました。')});
  const ktPreview=document.getElementById('kintonePreviewBtn');if(ktPreview)ktPreview.addEventListener('click',function(){showNotice('success','プレビュー完了','マッピング内容を確認しました。次に同期を実行できます。')});

  function setRespondentStep(step){document.querySelectorAll('.respondent-step .step').forEach(function(s){s.classList.toggle('active',s.dataset.rstep===String(step))});document.querySelectorAll('.respondent-screen').forEach(function(s){s.classList.remove('active')});const target=document.getElementById(step===1?'rinfo':step===2?'rquestions':'rdone');if(target)target.classList.add('active')}
  const start=document.getElementById('startAnswerBtn');if(start)start.addEventListener('click',function(){const org=document.getElementById('rOrg');const email=document.getElementById('rEmail');if(!org||!email)return;if(!org.value.trim()||!email.value.trim()){showNotice('error','入力してください','組織名とメールアドレスは必須です。');return}setRespondentStep(2)});
  const submit=document.getElementById('submitAnswerBtn');if(submit)submit.addEventListener('click',function(){submit.disabled=true;setTimeout(function(){submit.disabled=false;setRespondentStep(3)},500)});
  const noticeClose=document.getElementById('noticeClose');if(noticeClose)noticeClose.addEventListener('click',function(){const n=document.getElementById('notice');if(n)n.classList.remove('show')});
  const modalCancel=document.getElementById('modalCancel');if(modalCancel)modalCancel.addEventListener('click',function(){const m=document.getElementById('confirmModal');if(m)m.classList.remove('show')});

  showPage('surveys');
});
</script>
</body>
</html>